INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7698073, 1262962, 87808, '<td valign="top">Crickey this is amazing!</td>', 'Crickey this is amazing!', '2021-07-26 12:11:30.000000', NULL, 1),
(7698074, 1263033, 87808, '<td valign="top">Stunning as usually.</td>', 'Stunning as usually.', '2021-07-26 12:12:12.000000', NULL, 1),
(7698179, 1263028, 4008, '<td valign="top">Did you zoom the cityscape four times within one exposure (to achieve this result within standard editing) ? Creative approach.</td>', 'Did you zoom the cityscape four times within one exposure (to achieve this result within standard editing) ? Creative approach.', '2021-07-29 05:36:52.000000', NULL, 1),
(7698180, 1263015, 4008, '<td valign="top">The image is rather straight on. Would a view at an angel from the right side have been more appealing? You would have avoided the dark right side of the image and maybe the sign in front of the diner would have added atmosphere?</td>', 'The image is rather straight on. Would a view at an angel from the right side have been more appealing? You would have avoided the dark right side of the image and maybe the sign in front of the diner would have added atmosphere?', '2021-07-29 05:39:32.000000', NULL, 1),
(7698181, 1262972, 4008, '<td valign="top">I am thinking what the image would be without the title. Still clear but less so.</td>', 'I am thinking what the image would be without the title. Still clear but less so.', '2021-07-29 05:41:44.000000', NULL, 1),
(7698182, 1263033, 4008, '<td valign="top">I like it how all the buildings show plenty of detail while the whole image still shows this night atmosphere.</td>', 'I like it how all the buildings show plenty of detail while the whole image still shows this night atmosphere.', '2021-07-29 05:44:39.000000', NULL, 1),
(7698183, 1263023, 4008, '<td valign="top">It might be at night but does not have that atmosphere. Also the way the subject is shot is rather standard, as if it is a shot in passing by.</td>', 'It might be at night but does not have that atmosphere. Also the way the subject is shot is rather standard, as if it is a shot in passing by.', '2021-07-29 05:45:50.000000', NULL, 1),
(7698243, 1262962, 42733, '<td valign="top">In my top four.</td>', 'In my top four.', '2021-07-30 09:58:42.000000', NULL, 1),
(7698244, 1263032, 42733, '<td valign="top">In my top four.</td>', 'In my top four.', '2021-07-30 09:58:51.000000', NULL, 1),
(7698245, 1263027, 42733, '<td valign="top">In my top four.</td>', 'In my top four.', '2021-07-30 09:59:00.000000', NULL, 1),
(7698246, 1263033, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2021-07-30 09:59:10.000000', NULL, 1),
(7698250, 1263028, 163081, '<td valign="top">What filter are you using?</td>', 'What filter are you using?', '2021-07-30 11:48:39.000000', NULL, 1),
(7698256, 1263018, 100393, '<td valign="top">I really like the gritty feel, stark lighting and contrast here. The deep DoF really works to give a broad context to the scene.</td>', 'I really like the gritty feel, stark lighting and contrast here. The deep DoF really works to give a broad context to the scene.', '2021-07-30 13:34:15.000000', NULL, 1),
(7698257, 1263013, 100393, '<td valign="top">Captures how night vision feels. Nicely found.</td>', 'Captures how night vision feels. Nicely found.', '2021-07-30 13:34:48.000000', NULL, 1),
(7698258, 1263027, 100393, '<td valign="top">Uber-symmetry! A last (grand) outpost before the night.</td>', 'Uber-symmetry! A last (grand) outpost before the night.', '2021-07-30 13:35:46.000000', NULL, 1),
(7698259, 1263033, 100393, '<td valign="top">Makes me think of that line in Contact: "They''re alive!" before we rush on too.</td>', 'Makes me think of that line in Contact: "They''re alive!" before we rush on too.', '2021-07-30 13:36:36.000000', NULL, 1),
(7698260, 1263015, 100393, '<td valign="top">Great mood. I can hear the hum of the neon.</td>', 'Great mood. I can hear the hum of the neon.', '2021-07-30 13:36:58.000000', NULL, 1),
(7698261, 1263031, 100393, '<td valign="top">The title certainly adds to this sparing image and brings a good deal of context by so doing. A commentary on the world today.</td>', 'The title certainly adds to this sparing image and brings a good deal of context by so doing. A commentary on the world today.', '2021-07-30 13:37:53.000000', NULL, 1),
(7698262, 1263020, 100393, '<td valign="top">The top left window makes this for me - a sense of scale emerging from the inky blackness.</td>', 'The top left window makes this for me - a sense of scale emerging from the inky blackness.', '2021-07-30 13:38:44.000000', NULL, 1),
(7698263, 1262962, 100393, '<td valign="top">Ha! Was this done with a drone? That''s bold.</td>', 'Ha! Was this done with a drone? That''s bold.', '2021-07-30 13:39:36.000000', NULL, 1),
(7698264, 1263024, 100393, '<td valign="top">Certainly captures the movement of driving. I like the echoing of the colours of the lights and the sky.</td>', 'Certainly captures the movement of driving. I like the echoing of the colours of the lights and the sky.', '2021-07-30 13:40:32.000000', NULL, 1),
(7698265, 1263034, 100393, '<td valign="top">Great title. What a critter!</td>', 'Great title. What a critter!', '2021-07-30 13:41:03.000000', NULL, 1),
(7698266, 1263032, 100393, '<td valign="top">Impressed by the stability of this image given the (inevitable) exposure time. I think this gives a great sense of a populated landscape.</td>', 'Impressed by the stability of this image given the (inevitable) exposure time. I think this gives a great sense of a populated landscape.', '2021-07-30 13:42:10.000000', NULL, 1),
(7698267, 1262972, 100393, '<td valign="top">But do you want to go in? I like the grimy feel of everything that isn''t the ''neon''. Having said that, the missing LEDs tell their own story too.</td>', 'But do you want to go in? I like the grimy feel of everything that isn''t the ''neon''. Having said that, the missing LEDs tell their own story too.', '2021-07-30 13:43:33.000000', NULL, 1),
(7698268, 1263035, 100393, '<td valign="top">Honestly, I can''t say this is my cup of tea but it is a bold abstraction of the consequences of photons falling where photons will.</td>', 'Honestly, I can''t say this is my cup of tea but it is a bold abstraction of the consequences of photons falling where photons will.', '2021-07-30 13:44:43.000000', NULL, 1),
(7698269, 1263028, 100393, '<td valign="top">Who''d have thought leading lines could be demonstrated so effectively in a scene such as this. Outstanding sense of depth.</td>', 'Who''d have thought leading lines could be demonstrated so effectively in a scene such as this. Outstanding sense of depth.', '2021-07-30 13:45:30.000000', NULL, 1),
(7698270, 1262878, 100393, '<td valign="top">Like a close encounter. Wonderful colour.</td>', 'Like a close encounter. Wonderful colour.', '2021-07-30 13:45:55.000000', NULL, 1),
(7698271, 1263023, 100393, '<td valign="top">I''m not sure the stark lighting and subject matter grab me but the more I look at it the more I feel like I am on an evening stroll myself passing by the doors of others. A grower!</td>', 'I''m not sure the stark lighting and subject matter grab me but the more I look at it the more I feel like I am on an evening stroll myself passing by the doors of others. A grower!', '2021-07-30 13:47:18.000000', NULL, 1),
(7698312, 1263023, 30214, '<td valign="top">It may have been shot at night, but I''m afraid it does not have a night feel...</td>', 'It may have been shot at night, but I''m afraid it does not have a night feel...', '2021-07-31 15:48:16.000000', NULL, 1),
(7698313, 1263015, 30214, '<td valign="top">A nod to Edward Hopper? :)</td>', 'A nod to Edward Hopper? :)', '2021-07-31 15:49:30.000000', NULL, 1),
(7698314, 1263028, 30214, '<td valign="top">Very ominous!</td>', 'Very ominous!', '2021-07-31 15:49:52.000000', NULL, 1),
